-- RESEARCH-CLUSTER-CLOSEOUTS-1 (2026-10-26, session rem-a1, pillars research, cost and autonomy). Closing probes for 21 open agent_issues of the research cluster, each measured against live qnfo-audit,
-- living-paper and the repository on 2026-10-26 before it was written. A probe measures the condition the issue names; none observes the issue's own status (CLOSE-PROBE-CIRCULAR-1).
--   closes when it passes (the defect is fixed): 1000325 (cost-first model order live), 1000019 (the confirm lane settles), 1000062 (version bumps are live-verified), 1000040 (no out-of-scope retraction stands),
--     1000004 (grandfather decision, option a, recorded), 1000167 (identifier policy of the owner, OAI-PMH and JSON-LD identifiers live), and the seven RESEARCH-TERMINAL issues 100205, 100284, 100336, 100340, 100363, 100369, 100398.
--   closes when the outcome arrives (the lever is applied): 100408 (7 complete days within the neuron envelope, first possible 2026-10-29), 1000029 (no row cycles through revise, first possible 2026-10-27 10:03Z),
--     100449 (rows 50, 58, 86 settled once the oldest-first confirm is live), 1000293 (no paper with two open errata rows, after migrations/2026-10-26-errata-remediation-merge.sql), 100624 (revise_count written).
--   open on a code marker not yet on main: 1000037 (MIRROR-DRIFT-1), 1000012 (NOTICE-REPAIR-ESCALATE-1), 1000039 (PAPER-BODY-RETENTION-1).
-- The seven RESEARCH-TERMINAL contracts were 'monitoring' (loop-owned, never probed) with a research-terminal-* contract that needs terminal_rearms >= 2, which a row parked by PARKED-POISON-1 (recover_count 3, status archived) never reaches.
-- Rows written: remediation_contracts 21 (upsert on class), control_registry 1 (evidence appended), decision_log 3. No DELETE, no DROP.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:rollback RESEARCH-CLUSTER-CLOSEOUTS-1' WHERE class IN ('issue-1000325', 'issue-1000019', 'issue-100449', 'issue-100408', 'issue-1000062', 'issue-1000040', 'issue-1000004', 'issue-1000293', 'issue-1000029', 'issue-100624', 'issue-1000037', 'issue-1000012', 'issue-1000039', 'issue-1000167', 'issue-100205', 'issue-100284', 'issue-100336', 'issue-100340', 'issue-100363', 'issue-100369', 'issue-100398') AND precondition LIKE 'RESEARCH-CLUSTER-CLOSEOUTS-1%'; UPDATE control_registry SET evidence = substr(evidence, 1, instr(evidence, ' | PUBLISH-FLOOR-DATA-GAP-1') - 1) WHERE control = 'publish-floor-new-paper' AND instr(evidence, ' | PUBLISH-FLOOR-DATA-GAP-1') > 0;

-- 1. the decisions (append-only)
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-rem-a1', 'the closing measure of issue 1000029 must measure the defect it names (publications capped by re-draft loops), not reach zero only if revise can never fail, which is the declined waiver; the waiver stays declined because REVISE-NO-UNREVISED-1 (0.13.0, issue 2211) replaced advance-on-noop after it published papers whose HARD review findings no edit had applied', 'REVISE-NOOP-DOD-REPLACE-1: the probe of issue 1000029 is replaced by the largest number of revise to ground or parked moves of one row in 2880 minutes (at most 3) and the number of rows re-queued from ground after a revise no-op (at most 10); issue 100624 gets a probe on research_queue.revise_count', 'content_stage_events research, from_stage revise, last 2880 minutes (2026-10-26 18:20Z): to review 121, to complete 24, to revise 19, to parked 10 over 7 items, to ground 1; one row (rem-rev-b9f3a431) had 4 moves to parked between 2026-10-24T20:11Z and 2026-10-25T10:02Z; cloud_ops_events revise-noop per day: 264 on 10-20, 106 on 10-21, 47 on 10-24, 11 on 10-25, 6 on 10-26 (4 rows)', 'applied by migration', 'remediation_contracts issue-1000029 and issue-100624 only; no worker change, no gate, cap or probe weakened (the replaced probe could only pass if revise could never fail)', 'the Rollback line of migrations/2026-10-26-research-cluster-closeouts.sql restores the contracts to superseded; the old probe text is in remediation_verifications', 'the fleet closes a revise-livelock issue on a measure of the livelock', 'issue 1000029 passes once no row has more than 3 revise to ground or parked moves in 48 hours (the last 4-move row ages out at 2026-10-27T10:03Z) and revise re-queues from ground stay at 10 or fewer', 'research throughput: rows stop cycling through full re-drafts', 'content_stage_events and cloud_ops_events read on 2026-10-26; PARK-REARM-CAP-1 live as 0.36.7'
WHERE NOT EXISTS (SELECT 1 FROM decision_log x WHERE x.action LIKE 'REVISE-NOOP-DOD-REPLACE-1:%');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-rem-a1', 'truncating or unpublishing published papers to satisfy a length guard that was added later would be a silent drop of the published record, and the owner directed on 2026-10-26 that no gate withdraws a published or owner paper', 'PUBLISH-FLOOR-DATA-GAP-1: option (a) is chosen: the 20,000-character floor applies to new pipeline papers and to writes, published papers below it are grandfathered and improve through the revision loop and COMPLETE-TO-FLOOR-1; recorded in control_registry publish-floor-new-paper', 'living-paper 2026-10-26 18:30Z: 100 of 704 published papers are under 20,000 characters (70 on 2026-10-24; the gate restore of 2026-10-26 07:21Z returned 30 more); papers_live_failing_release_gate = 246 keeps them visible', 'applied by migration', 'control_registry evidence text and one contract; no trigger or paper changes', 'the Rollback line of migrations/2026-10-26-research-cluster-closeouts.sql removes the appended evidence', 'the length policy for published papers is written down', 'issue 1000004 closes on its probe once the record exists', 'reach: no published paper is withdrawn for its length', 'living-paper papers read-only; control_registry row publish-floor-new-paper read'
WHERE NOT EXISTS (SELECT 1 FROM decision_log x WHERE x.action LIKE 'PUBLISH-FLOOR-DATA-GAP-1:%');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-rem-a1', 'an issue closes on a probe that measures the condition it names; a research_queue row parked by PARKED-POISON-1 has spent every automatic recovery (recover_count 3) even though terminal_rearms stays 0, so the research-terminal probe that needs terminal_rearms >= 2 can never pass for it', 'RESEARCH-CLUSTER-CLOSEOUTS-1: replaced the closing probe of 21 research-cluster issues (list in the file header) and gave the seven RESEARCH-TERMINAL issues a probe that accepts a left-terminal row or a PARKED-POISON-1 row with the queue advancing', 'contracts read 2026-10-26 18:20Z: issues 100408, 100449, 100624, 1000004, 1000012, 1000037, 1000039, 1000040, 1000062 had only the closure-observing probe (superseded), 1000325 and the seven RESEARCH-TERMINAL issues were monitoring (loop-owned, not probed), 1000019 required a pre-2026-10-23 backlog of 275 rows to be empty; rows: idea-reality-idempotent... published 2026-10-21, e087b53b deferred at revise (backpressure), five rem- rows archived/parked at recover_count 3', 'applied by migration', 'remediation_contracts only; the hourly remediation tick closes an issue whose probe passes, with its evidence row', 'the Rollback line of migrations/2026-10-26-research-cluster-closeouts.sql supersedes the contracts again', 'the closing path of the research cluster measures the defects', 'each closing probe passes when its condition holds; five fail on purpose until an outcome arrives or a code marker lands (listed in the header)', 'research integrity: no issue closes on its own status', 'remediation_contracts, v_issue_age_ladder, living-paper papers, ai_call_counters, cloud_ops_events, metric_registry read on 2026-10-26'
WHERE NOT EXISTS (SELECT 1 FROM decision_log x WHERE x.action LIKE 'RESEARCH-CLUSTER-CLOSEOUTS-1:%');

-- 2. the grandfather decision in the control registry
UPDATE control_registry SET evidence = evidence || ' | PUBLISH-FLOOR-DATA-GAP-1 (2026-10-26): published papers under 20,000 characters (100 of 704 on 2026-10-26) are grandfathered; the floor is a gate on new pipeline papers and on writes, never a reason to cut or withdraw a published paper; they stay visible in papers_live_failing_release_gate and improve through the revision loop and COMPLETE-TO-FLOOR-1.', reviewed_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
 WHERE control = 'publish-floor-new-paper' AND instr(COALESCE(evidence, ''), 'PUBLISH-FLOOR-DATA-GAP-1') = 0;

-- 3. the closing probes (upsert on class: a row of the same class is replaced, never duplicated)
INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000325', 1000325, 'RESEARCH-CLUSTER-CLOSEOUTS-1: every ordinary research call starts with the lower-cost model (issue 1000325)', 'none: qnfo-research-exec 0.36.0 (RESEARCH-COST-FIRST-1) picks glm-5.3-flash first on every tick and reverts on its own to gpt-oss-120b first for an hour after 10 empty replies; this probe reads the model-order event of the last 90 minutes, so it fails if the order is reverted or the worker stops writing it', 'SELECT ''@cf/zai-org/glm-5.3-flash'' AS expected, COALESCE((SELECT CASE WHEN instr(text, ''@cf/zai-org/glm-5.3-flash'') > 0 AND instr(text, ''automatic revert'') = 0 THEN ''@cf/zai-org/glm-5.3-flash'' ELSE substr(text, 1, 90) END FROM cloud_ops_events WHERE job = ''qnfo-research-exec'' AND kind = ''model-order'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-90 minutes'') ORDER BY ts DESC LIMIT 1), ''no model-order event in 90 minutes'') AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000019', 1000019, 'RESEARCH-CLUSTER-CLOSEOUTS-1: the internal confirm settles its candidates instead of deferring all of them (issue 1000019)', 'none: ERRATA-CONFIRM-COST-1 (research-exec 0.34.0, deepseek-v4-flash first) and ERRATA-DEFER-SINK-1 (0.37.1, oldest first, a deferring row sinks) keep the lane settling; the backlog is a capacity matter tracked by issues 100449, 1000002 and 100456', 'WITH t AS (SELECT json_extract(value, ''$.ts'') AS ts, COALESCE(json_extract(value, ''$.internal_confirm.candidates''), 0) AS cand, COALESCE(json_extract(value, ''$.internal_confirm.deferred''), 0) AS def FROM errata_watch WHERE key = ''tick:errata-watch''), d AS (SELECT COUNT(*) AS n FROM errata_queue WHERE source = ''internal_audit'' AND status IN (''detected'', ''rejected'', ''no-paper'') AND updated_at >= datetime(''now'', ''-24 hours'')) SELECT ''ok'' AS expected, CASE WHEN t.ts IS NULL OR t.ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-150 minutes'') THEN ''stale: the errata-watch tick has not run since '' || COALESCE(t.ts, ''never'') WHEN t.cand > 0 AND t.def * 2 > t.cand THEN ''deferring: '' || t.def || '' of '' || t.cand || '' candidates deferred'' WHEN d.n < 50 THEN ''slow: '' || d.n || '' internal errata settled in 24 h'' ELSE ''ok'' END AS observed FROM d LEFT JOIN t ON 1 = 1', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-100449', 100449, 'RESEARCH-CLUSTER-CLOSEOUTS-1: the three head rows named in the definition of done leave internal-open (issue 100449)', 'none: the selector was ORDER BY RANDOM() and a defer wrote nothing; ERRATA-DEFER-SINK-1 (research-exec 0.37.1, errata-hub 1.9.1) takes the oldest rows first and touches a row that defers, and every defer is a cloud_ops_events row (errata_confirm_defer). Rows 58 and 86 are settled (implemented); row 50 is the oldest internal-open row, so the first hourly tick after the deploy takes it', 'SELECT ''settled'' AS expected, CASE WHEN (SELECT COUNT(*) FROM errata_queue WHERE id IN (50, 58, 86) AND status = ''internal-open'') = 0 THEN ''settled'' ELSE (SELECT COUNT(*) FROM errata_queue WHERE id IN (50, 58, 86) AND status = ''internal-open'') || '' of the three head rows 50, 58, 86 are still internal-open'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-100408', 100408, 'RESEARCH-CLUSTER-CLOSEOUTS-1: research and errata spend stays within the COST-SUSTAIN-1 envelope for 7 complete days while publishing continues (issue 100408)', 'none: the lever is the hard daily neuron budget (ops_config research_daily_neurons, 360000) and the cost-first model order (0.36.0); the first day that can pass is 2026-10-29 (2026-10-20 and 2026-10-21 spent 3.6M and 1.75M neurons). Per-paper efficiency is tracked by research_neurons_per_publication_7d (issue 100464) and issue 1000031', 'WITH d AS (SELECT day, SUM(neurons) AS n FROM ai_call_counters WHERE worker IN (''qnfo-research-exec'', ''errata-hub'') AND day BETWEEN date(''now'', ''-7 days'') AND date(''now'', ''-1 day'') GROUP BY day), p AS (SELECT COUNT(*) AS n FROM research_queue WHERE status = ''published'' AND published_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'')) SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM d) < 7 THEN ''pending: only '' || (SELECT COUNT(*) FROM d) || '' of the last 7 complete days have a spend row'' WHEN (SELECT COUNT(*) FROM d WHERE n > 600000) > 0 THEN ''over: '' || (SELECT COUNT(*) FROM d WHERE n > 600000) || '' of the last 7 complete days spent more than 600000 neurons (highest '' || CAST((SELECT MAX(n) FROM d) AS INTEGER) || '')'' WHEN (SELECT n FROM p) < 14 THEN ''output collapsed: '' || (SELECT n FROM p) || '' papers published in 7 days'' ELSE ''ok'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000062', 1000062, 'RESEARCH-CLUSTER-CLOSEOUTS-1: a version bump is tied to a verified deploy, read back from the running worker (issue 1000062)', 'none: canonical-deploy.yml polls /health of every control-plane worker for the pushed VERSION and reverts on a miss (canary_revert.py), deploy_drift_cf redeploys any worker whose live VERSION is behind main, and the two metrics read here count a merged version that is not live (merges_undeployed_over_60m, drift_total), each with a trigger', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM metric_registry WHERE metric IN (''merges_undeployed_over_60m'', ''drift_total'') AND datetime(last_refreshed) >= datetime(''now'', ''-3 hours'')) < 2 THEN ''stale: a deploy-verification metric has not refreshed in 3 hours'' WHEN COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''merges_undeployed_over_60m''), 1) > 0 THEN ''merged versions not live after 60 minutes: '' || (SELECT last_value FROM metric_registry WHERE metric = ''merges_undeployed_over_60m'') WHEN COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''drift_total''), 1) > 0 THEN ''repository and live versions drift: '' || (SELECT last_value FROM metric_registry WHERE metric = ''drift_total'') ELSE ''ok'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000040', 1000040, 'RESEARCH-CLUSTER-CLOSEOUTS-1: no retraction stands outside the claim sweep''s own scope (issue 1000040)', 'none: radix-agnostic-dsi-detection and ultrametric-physics-m1-ratio-based-valuation-theory were restored with their pre-retraction bodies by the gate restore of 2026-10-26 07:21Z (both published, 14,086 and 12,831 characters); the 28 papers that stay retracted all carry a qnf- identifier, which is the sweep''s own scope (rlEligible), and each keeps its backup in paper_integrity_backups', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM papers WHERE status = ''retracted'' AND identifier NOT LIKE ''qnf-%'') AS TEXT) AS observed', 'd1-query@living-paper', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000004', 1000004, 'RESEARCH-CLUSTER-CLOSEOUTS-1: the grandfathering of published papers under the length floor is decided and documented (issue 1000004)', 'none: option (a) of the issue, consistent with PUBLICATION-GATE-AUDIT-1 (publish-floor-new-paper: the floor applies to new pipeline papers only, never to a published or owner paper); recorded in control_registry and decision_log; the papers stay visible in papers_live_failing_release_gate and improve through the revision loop and COMPLETE-TO-FLOOR-1', 'SELECT ''documented'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM control_registry WHERE control = ''publish-floor-new-paper'' AND disposition = ''keep'' AND instr(evidence, ''PUBLISH-FLOOR-DATA-GAP-1'') > 0) AND EXISTS (SELECT 1 FROM decision_log WHERE instr(action, ''PUBLISH-FLOOR-DATA-GAP-1'') > 0) THEN ''documented'' ELSE ''the grandfather decision is not recorded'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000293', 1000293, 'RESEARCH-CLUSTER-CLOSEOUTS-1: no paper has two open errata remediation rows (issue 1000293)', 'none: routeHighRiskErrata (research-exec 0.37.0, errata-hub 1.9.0) makes one row per paper and appends later errata to the waiting row; migrations/2026-10-26-errata-remediation-merge.sql merged the 84 duplicates that were already queued', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM (SELECT paper_slug FROM research_queue WHERE source = ''remediation'' AND source_id LIKE ''errata:%'' AND paper_slug IS NOT NULL AND status IN (''queued'', ''deferred'', ''researching'', ''review'') GROUP BY paper_slug HAVING COUNT(*) > 1)) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000029', 1000029, 'RESEARCH-CLUSTER-CLOSEOUTS-1: a revise no-op no longer cycles a row through ground and parked (issue 1000029, definition replaced by issue 1000456)', 'none: the waiver is declined (REVISE-NO-UNREVISED-1 publishes nothing whose HARD findings no edit applied); the livelock is bounded by PARK-REARM-CAP-1 (0.36.7, terminal_rearms) and REVISE-NOOP-BOUND-1 (code loop task ct_rvnp3b02c956c0, revise_count); the measure is the largest number of revise to ground or parked moves of one row in 2880 minutes (4 on 2026-10-26, the last at 2026-10-25T10:02Z) and the number of re-queues from ground', 'WITH ev AS (SELECT item_id, COUNT(*) AS n FROM content_stage_events WHERE flow = ''research'' AND from_stage = ''revise'' AND to_stage IN (''ground'', ''parked'') AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-2880 minutes'') GROUP BY item_id) SELECT ''ok'' AS expected, CASE WHEN COALESCE((SELECT MAX(n) FROM ev), 0) > 3 THEN ''cycling: one row had '' || (SELECT MAX(n) FROM ev) || '' revise to ground or parked moves in 2880 minutes'' WHEN (SELECT COUNT(*) FROM content_stage_events WHERE flow = ''research'' AND from_stage = ''revise'' AND to_stage = ''ground'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-2880 minutes'')) > 10 THEN ''redrafting: more than 10 rows re-queued from ground after a revise no-op in 2880 minutes'' ELSE ''ok'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-100624', 100624, 'RESEARCH-CLUSTER-CLOSEOUTS-1: research_queue.revise_count is written when a revise no-op happens (issue 100624)', 'code loop task ct_rvnp3b02c956c0 (REVISE-NOOP-BOUND-1) increments revise_count on every revise no-op and parks the row at 2; this probe reads the column itself, which is 0 on every row until that code is live and a no-op happens', 'SELECT ''increments'' AS expected, CASE WHEN (SELECT COALESCE(MAX(revise_count), 0) FROM research_queue) > 0 THEN ''increments'' ELSE ''revise_count is 0 on every row of research_queue'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
