INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000037', 1000037, 'RESEARCH-CLUSTER-CLOSEOUTS-1: the R2 paper mirror is repaired when it drifts from body_md (issue 1000037, path (b))', 'path (a), the versioned notice key written before the canonical key, is on main (PR 4667, research-exec 0.36.6); path (b), a bounded mirror-drift repair in the hourly notice-repair tick, carries the marker MIRROR-DRIFT-1 and is the open part', '{"paths":["qnfo-research-exec/worker.js"],"contains":"MIRROR-DRIFT-1"}', 'code-read', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
