INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-1000167', 1000167, 'RESEARCH-CLUSTER-CLOSEOUTS-1: papers carry a persistent identifier that is not a dead DOI (issue 1000167)', 'none: the owner''s decision of 2026-10-26 (human_actions 175, default adopted) is no DOIs; papers keep immutable versioned URLs, content hashes, CITATION.cff and OAI-PMH as identifiers (BP26-PAPER-PIDS-1, issue 1000338, open). Measured 2026-10-26 18:35Z: https://papers.qnfo.org/oai answers Identify and ListRecords with oai:papers.qnfo.org:<slug> identifiers, and a paper page carries a JSON-LD identifier (QNFO-OAI-ID and URL) and no 10.5281 text', '{"url":"https://papers.qnfo.org/papers/completeness-senses-levi-civita","status":200,"contains":"QNFO-OAI-ID","absent":"10.5281/zenodo","max_ms":15000}', 'runner-https', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-100205', 100205, 'RESEARCH-CLUSTER-CLOSEOUTS-1: research_queue row rem-0039d25b- has left the terminal state, or every automatic recovery is spent and the queue advances (issue 100205)', 'none: the row is published or back in the pipeline, or parked with its reason after recover_count reached the ceiling (PARKED-POISON-1: no sweep re-arms an archived rem- row); the earlier probes of this issue observed only the issue''s own status (PROBE-REVIEW-1 refused them) or required terminal_rearms >= 2, which PARKED-POISON-1 never sets', 'SELECT ''resolved'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM research_queue WHERE id = ''rem-0039d25b-ef66-41ed-b128-f78f7037b092'' AND status NOT IN (''wontfix'', ''archived'') AND COALESCE(stage, '''') <> ''parked'') THEN ''resolved'' WHEN EXISTS (SELECT 1 FROM research_queue WHERE id = ''rem-0039d25b-ef66-41ed-b128-f78f7037b092'' AND stage = ''parked'' AND status IN (''wontfix'', ''archived'') AND (terminal_rearms >= 2 OR (recover_count >= 3 AND instr(error, ''PARKED-POISON-1'') = 1))) AND EXISTS (SELECT 1 FROM cloud_ops_events WHERE job = ''qnfo-research-exec'' AND status = ''ok'' AND instr(text, ''->'') > 0 AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-26 hours'')) THEN ''resolved'' ELSE ''pending'' END AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

